async function call(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});let data;try{data=await r.json();}catch{throw Error('Focus service is unavailable. Try Refresh.');}if(!r.ok){const e=Error(data.error||'Request failed');e.activeId=data.activeId;throw e;}return data;}
async function load(){if(!storageOK){message('Focus history needs browser storage for its device key. Try another browser profile.',true);return;}$('focusSync').textContent='Connecting…';try{const data=await call('state');settings=validateSettings(data.settings);revision=data.revision;logs=data.logs;profile=data.profile;ready=true;$('focusSync').textContent='Focus history connected';if(timer?.kind==='focus'&&logs.some(x=>x.id===timer.id)){timer=null;storeTimer();}renderSettings();renderAll();bridge();}catch(e){ready=false;$('focusSync').textContent='Focus storage unavailable';message(e.message,true);}renderTimer();}
