function renderSettings(){for(const[id,key]of[['breakMinutes','breakMinutes'],['breakActivity','breakActivity'],['dailyGoal','goal']])$(id).value=settings[key];$('blockedDomains').value=settings.domains.join('\n');$('allowedChannels').value=settings.channels.join('\n');for(const[id,key]of[['hideShorts','shorts'],['hideReels','reels'],['studyYoutube','youtube'],['focusGuard','guard'],['autoBlock','autoBlock']])$(id).checked=settings[key];$('studyAlias').value=profile.alias;$('examGroup').value=profile.exam;$('publicLeaderboard').checked=profile.public;$('domainLimits').innerHTML=settings.limits.map((x,i)=>`<div class="limit-row"><span>${esc(x.domain)} · ${x.minutes} min/day</span><button class="quiet" data-remove-limit="${i}" aria-label="Remove limit for ${esc(x.domain)}">Remove</button></div>`).join('');}
function view(which){tab=which;root.querySelectorAll('[data-focus-tab]').forEach(b=>{const yes=b.dataset.focusTab===which;b.setAttribute('aria-selected',String(yes));b.tabIndex=yes?0:-1;});for(const s of ['timer','schedule','wellbeing','insights','community'])$('ft-'+s).hidden=s!==which;if(which==='community'){refreshRoom();refreshLeaderboard();}if(which==='insights')renderInsights();}
root.querySelector('.focus-nav').onclick=e=>{const b=e.target.closest('[data-focus-tab]');if(b)view(b.dataset.focusTab);};root.querySelector('.focus-nav').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const buttons=[...root.querySelectorAll('[data-focus-tab]')],i=buttons.findIndex(b=>b.dataset.focusTab===tab),n=e.key==='Home'?0:e.key==='End'?4:(i+(e.key==='ArrowLeft'?-1:1)+5)%5;view(buttons[n].dataset.focusTab);buttons[n].focus();}};
