function clock(seconds){const n=Math.max(0,Math.floor(seconds)),h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;return h?`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;}
function renderTimer(){const active=!!timer,strict=active&&timer.strict&&timer.kind==='focus';$('startTimer').hidden=active;$('startTimer').disabled=!ready||finishBusy;$('pauseTimer').hidden=!active||timer?.kind==='break'||!!timer?.pending;$('endTimer').hidden=!active;$('pauseTimer').disabled=strict||finishBusy;$('endTimer').disabled=!!(strict&&timerRemaining(timer)>0&&!timer?.pending||finishBusy);$('pauseTimer').textContent=timer?.running?'Pause':'Resume';$('endTimer').textContent=timer?.pending?'Retry save':timer?.kind==='break'?'Finish break':timer?.mode==='stopwatch'?'Finish & save':'End early';for(const id of ['focusSubject','focusDuration','strictTimer'])$(id).disabled=active;$('strictTimer').disabled=active||mode==='stopwatch';root.querySelectorAll('[data-mode]').forEach(b=>{b.disabled=active;b.setAttribute('aria-pressed',String(b.dataset.mode===(timer?.mode||mode)));});$('durationWrap').hidden=mode==='stopwatch'&&!timer;$('timerPhase').textContent=timer?.kind==='break'?'REST IS PART OF THE WORK':active?`${timer.subject} · ${timer.mode==='pomodoro'?'ROUND '+round:timer.mode.toUpperCase()}`:'ONE SESSION. ONE THING.';$('timerClock').textContent=timer?clock(timer.mode==='stopwatch'&&timer.kind==='focus'?elapsedMs(timer)/1000:Math.ceil(timerRemaining(timer)/1000)):clock(mode==='stopwatch'?0:Number($('focusDuration').value||25)*60);$('timerHint').textContent=finishBusy?'Saving your session…':timer?.kind==='break'?settings.breakActivity:active?(timer.running?(strict?'Commitment mode · keep going':'One step at a time'):'Paused · take a breath'):'Ready when you are';const fraction=timer&&timer.duration?Math.min(1,elapsedMs(timer)/(timer.duration*1000)):0;$('timerRing').style.setProperty('--progress',`${fraction*360}deg`);$('linkedLabel').hidden=!linkedTask&&!timer?.linked;$('linkedLabel').textContent='Linked assignment: '+(timer?.linked?.title||linkedTask?.title||'');}
root.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(timer)return;mode=b.dataset.mode;if(mode==='stopwatch')$('strictTimer').checked=false;else $('focusDuration').value=mode==='pomodoro'?25:50;renderTimer();});$('focusDuration').oninput=renderTimer;
async function start(){if(timer||!ready||finishBusy)return;const subject=$('focusSubject').value.trim(),minutes=Number($('focusDuration').value);if(!subject||subject.length>40||mode!=='stopwatch'&&(!Number.isInteger(minutes)||minutes<1||minutes>720))return message('Enter a subject and 1–720 whole focus minutes.',true);finishBusy=true;renderTimer();try{const id=crypto.randomUUID(),duration=mode==='stopwatch'?43200:minutes*60;const data=await call('sessions/start','POST',{id,subject,mode,planned:duration,room:room||null});timer={id,subject,mode,duration,kind:'focus',anchor:Date.now(),accumulated:0,running:true,strict:mode!=='stopwatch'&&$('strictTimer').checked,interruptions:0,linked:linkedTask,serverStart:data.started};linkedTask=null;storeTimer();bridge();message('Focus started. Your timer survives page reloads.');}catch(e){message(e.message,true);if(e.activeId){const btn=document.createElement('button');btn.className='quiet';btn.textContent='End orphaned timer';btn.onclick=async()=>{if(confirm('End the previous timer without counting it as completed?'))try{await call('sessions/recover','POST',{});message('Previous timer cleared. You can start a new session.');}catch(err){message(err.message,true);}};$('focusMessage').append(' ',btn);}}finally{finishBusy=false;renderTimer();}}
$('startTimer').onclick=start;$('pauseTimer').onclick=()=>{if(!timer||timer.strict)return;if(timer.running){timer.accumulated=elapsedMs(timer);timer.running=false;}else{timer.anchor=Date.now();timer.running=true;}storeTimer();bridge();renderTimer();};
async function finish(early=false){if(!timer||finishBusy)return;if(timer.kind==='break'){timer=null;storeTimer();round++;renderTimer();message('Break finished. Start the next round when ready.');return;}if(early&&timer.strict&&timerRemaining(timer)>0&&!timer.pending)return;if(!timer.pending&&early&&timer.mode!=='stopwatch'&&!confirm('End early? This session will be saved as interrupted and will not count toward your streak or leaderboard.'))return;finishBusy=true;const current=timer;if(!current.pending){current.pending={id:current.id,seconds:Math.floor(Math.min(elapsedMs(current)/1000,current.duration)),status:current.mode==='stopwatch'||!early?'completed':'aborted',interruptions:current.interruptions||0};current.accumulated=elapsedMs(current);current.running=false;storeTimer();}renderTimer();try{const result=await call('sessions/finish','POST',current.pending);logs=[result.session,...logs.filter(x=>x.id!==current.id)];if(result.session.status==='completed'&&current.linked)window.dispatchEvent(new CustomEvent('rebound:credit',{detail:{sessionId:current.id,taskId:current.linked.taskId,minutes:Math.min(current.linked.minutes,Math.floor(result.session.seconds/60))}}));timer=null;if(current.mode==='pomodoro'&&result.session.status==='completed'){const duration=(round%4===0?Math.max(15,settings.breakMinutes):settings.breakMinutes)*60;timer={kind:'break',mode:'countdown',subject:'Mindful break',duration,anchor:Date.now(),accumulated:0,running:true,strict:false};}storeTimer();bridge();renderAll();message(result.session.status==='completed'?'Session saved. Give yourself a moment to reset.':'Interrupted session saved. A fresh start is still a start.');}catch(e){message('Could not save yet: '+e.message+' Your timer is retained; use Retry save.',true);}finally{finishBusy=false;renderTimer();}}
$('endTimer').onclick=()=>finish(!timer?.pending&&timer?.mode!=='stopwatch'&&timerRemaining(timer)>0);
setInterval(()=>{if(timer){renderTimer();if(timer.running&&timerRemaining(timer)<=0&&!finishBusy)finish(false);}const active=activeSchedule(settings.schedules);const key=active?dateKey()+active.id:'';if(active&&notificationShown!==key){notificationShown=key;message(`It’s time for ${active.subject}: ${active.start}–${active.end}. Start when ready.`);if('Notification'in window&&Notification.permission==='granted')new Notification('Rebound study block',{body:`${active.subject} · ${active.start}–${active.end}`});}},1000);
document.addEventListener('visibilitychange',()=>{if(timer?.kind==='focus'&&timer.running&&document.hidden){timer.interruptions=(timer.interruptions||0)+1;storeTimer();}else if(timer?.kind==='focus'&&settings.guard)message(`Welcome back. Your next step is ${timer.subject}. This session has ${timer.interruptions||0} tab departures.`);});
window.addEventListener('storage',e=>{if(e.key==='rebound-active-timer'){try{timer=JSON.parse(e.newValue||'null');renderTimer();}catch{}}});
window.addEventListener('rebound:focus',e=>{workspace('focus');view('timer');if(timer)return message('Finish your current timer before starting an assignment session.',true);linkedTask=e.detail;$('focusSubject').value=e.detail.subject;mode='countdown';$('focusDuration').value=e.detail.minutes;renderTimer();root.scrollIntoView({behavior:'smooth'});});
function renderToday(){const today=dateKey(),done=logs.filter(l=>l.status==='completed'&&dateKey(new Date(l.ended))===today),minutes=Math.floor(done.reduce((n,x)=>n+x.seconds,0)/60);$('todayFocus').textContent=minutes;$('goalProgress').max=settings.goal;$('goalProgress').value=minutes;$('goalText').textContent=`${minutes} of ${settings.goal} min daily goal`;$('streakStat').textContent=streakDays(logs,settings.goal);$('interruptStat').textContent=done.reduce((n,x)=>n+x.interruptions,0);const blocks=settings.schedules.filter(s=>s.days.includes(new Date().getDay())).sort((a,b)=>a.start.localeCompare(b.start));$('todayBlocks').innerHTML=blocks.length?blocks.map(s=>`<button class="today-block" data-study-block="${esc(s.id)}"><strong>${esc(s.subject)}</strong><span>${s.start}–${s.end}</span><small>Set timer</small></button>`).join(''):'<p class="muted">No study blocks today. Add a repeating routine to make space for your subjects.</p>';}
function renderSchedule(){$('weeklySchedule').innerHTML=[1,2,3,4,5,6,0].map(d=>`<div class="week-column"><h3>${weekdays[d]}</h3>${settings.schedules.filter(s=>s.days.includes(d)).sort((a,b)=>a.start.localeCompare(b.start)).map(s=>`<div class="schedule-block"><strong>${esc(s.subject)}</strong><span>${s.start}–${s.end}</span><button data-edit-block="${esc(s.id)}">Edit</button><button data-delete-block="${esc(s.id)}" aria-label="Delete ${esc(s.subject)} block">Remove</button></div>`).join('')||'<p class="small muted">Unscheduled</p>'}</div>`).join('');}
function renderInsights(){const complete=logs.filter(l=>l.status==='completed'),minutes=Math.floor(complete.reduce((n,x)=>n+x.seconds,0)/60),interruptions=logs.reduce((n,x)=>n+x.interruptions,0);$('insightStats').innerHTML=`<div><strong>${minutes}</strong><span>focus minutes</span></div><div><strong>${complete.length}</strong><span>completed sessions</span></div><div><strong>${streakDays(logs,settings.goal)}</strong><span>day streak</span></div><div><strong>${interruptions}</strong><span>tab departures</span></div>`;const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {label:weekdays[d.getDay()],minutes:Math.floor(complete.filter(l=>dateKey(new Date(l.ended))===dateKey(d)).reduce((n,x)=>n+x.seconds,0)/60)};});const max=Math.max(settings.goal,...days.map(d=>d.minutes));$('focusChart').innerHTML=days.map(d=>`<div class="chart-day"><span>${d.minutes}m</span><div><i style="height:${Math.max(1,d.minutes/max*100)}%"></i></div><span>${d.label}</span></div>`).join('');const subjects={};for(const l of complete)subjects[l.subject]=(subjects[l.subject]||0)+l.seconds;$('subjectChart').innerHTML=Object.entries(subjects).sort((a,b)=>b[1]-a[1]).map(([name,seconds])=>`<div class="subject-total"><span>${esc(name)}</span><strong>${Math.floor(seconds/60)} min</strong></div>`).join('')||'<p class="muted">Finish your first session to see a subject breakdown.</p>';$('milestones').innerHTML=[[complete.length>=1,'First step','Complete one session'],[minutes>=60,'An hour for you','Log 60 focus minutes'],[complete.length>=5,'Finding a rhythm','Complete five sessions'],[minutes>=300,'Five-hour milestone','Log 300 focus minutes']].map(([yes,title,sub])=>`<div class="milestone ${yes?'earned':''}"><span>${yes?'✓':'○'}</span><strong>${title}</strong><small>${sub}</small></div>`).join('');$('focusHistory').innerHTML=logs.length?`<table><thead><tr><th>Subject</th><th>Date</th><th>Duration</th><th>Mode</th><th>Status</th><th>Tab departures</th></tr></thead><tbody>${logs.slice(0,100).map(l=>`<tr><td>${esc(l.subject)}</td><td>${new Date(l.started).toLocaleString()}</td><td>${clock(l.seconds)}</td><td>${esc(l.mode)}</td><td>${esc(l.status)}</td><td>${l.interruptions}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">Your real sessions will appear here. There are no sample productivity scores.</p>';}
function renderAll(){renderToday();renderSchedule();renderInsights();renderTimer();}
function blockDialog(id){const s=settings.schedules.find(s=>s.id===id);$('blockForm').reset();$('blockId').value=id||'';$('blockSubject').value=s?.subject||'';$('blockStart').value=s?.start||'18:00';$('blockEnd').value=s?.end||'20:00';root.querySelectorAll('[name=blockDay]').forEach(c=>c.checked=(s?.days||[1,2,3,4,5]).includes(Number(c.value)));$('blockError').textContent='';$('blockHeading').textContent=id?'Edit study block':'New study block';$('blockDialog').showModal();}
$('addBlock').onclick=()=>blockDialog();$('closeBlock').onclick=()=>$('blockDialog').close();$('blockForm').onsubmit=async e=>{e.preventDefault();try{const id=$('blockId').value||crypto.randomUUID(),s=validateSchedule({id,subject:$('blockSubject').value,start:$('blockStart').value,end:$('blockEnd').value,days:[...root.querySelectorAll('[name=blockDay]:checked')].map(c=>Number(c.value))},settings.schedules);await saveSettings({...settings,schedules:[...settings.schedules.filter(x=>x.id!==id),s]});$('blockDialog').close();}catch(e){$('blockError').textContent=e.message;}};
$('weeklySchedule').onclick=async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.editBlock)blockDialog(b.dataset.editBlock);if(b.dataset.deleteBlock&&confirm('Remove this repeating block from every selected day?'))try{await saveSettings({...settings,schedules:settings.schedules.filter(s=>s.id!==b.dataset.deleteBlock)});}catch(e){message(e.message,true);}};
$('weekdayExample').onclick=async()=>{try{const next=[...settings.schedules];for(const [subject,start,end]of [['Physics','18:00','20:00'],['Chemistry','20:00','21:00']])next.push(validateSchedule({id:crypto.randomUUID(),subject,start,end,days:[1,2,3,4,5]},next));await saveSettings({...settings,schedules:next});}catch(e){message(e.message,true);}};
$('todayBlocks').onclick=e=>{const b=e.target.closest('[data-study-block]');if(!b)return;if(timer)return message('Finish your active session first.',true);const s=settings.schedules.find(s=>s.id===b.dataset.studyBlock);$('focusSubject').value=s.subject;mode='countdown';$('focusDuration').value=(Number(s.end.slice(0,2))*60+Number(s.end.slice(3)))-(Number(s.start.slice(0,2))*60+Number(s.start.slice(3)));linkedTask=null;view('timer');renderTimer();};$('openSchedule').onclick=()=>view('schedule');
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
$('exportCalendar').onclick=()=>{if(!settings.schedules.length)return message('Add study blocks before exporting.');download('rebound-weekly-study.ics',scheduleICS(settings.schedules),'text/calendar');};
$('saveBreaks').onclick=async()=>{try{await saveSettings({...settings,breakMinutes:Number($('breakMinutes').value),breakActivity:$('breakActivity').value});}catch(e){message(e.message,true);}};$('saveGoal').onclick=async()=>{try{await saveSettings({...settings,goal:Number($('dailyGoal').value)});}catch(e){message(e.message,true);}};
$('guardForm').onsubmit=async e=>{e.preventDefault();try{await saveSettings({...settings,domains:$('blockedDomains').value.split('\n'),channels:$('allowedChannels').value.split('\n').map(x=>x.trim()).filter(Boolean),shorts:$('hideShorts').checked,reels:$('hideReels').checked,youtube:$('studyYoutube').checked});}catch(e){message(e.message,true);}};
$('limitForm').onsubmit=async e=>{e.preventDefault();try{const domain=$('limitDomain').value.trim().toLowerCase();await saveSettings({...settings,limits:[...settings.limits.filter(x=>x.domain!==domain),{domain,minutes:Number($('limitMinutes').value)}]});$('limitDomain').value='';}catch(e){message(e.message,true);}};
$('domainLimits').onclick=async e=>{const b=e.target.closest('[data-remove-limit]');if(b)try{await saveSettings({...settings,limits:settings.limits.filter((_,i)=>i!==Number(b.dataset.removeLimit))});}catch(e){message(e.message,true);}};
$('focusGuard').onchange=async()=>{try{await saveSettings({...settings,guard:$('focusGuard').checked});}catch(e){message(e.message,true);}};$('autoBlock').onchange=async()=>{try{await saveSettings({...settings,autoBlock:$('autoBlock').checked});}catch(e){message(e.message,true);}};
$('enableNotifications').onclick=async()=>{if(!('Notification'in window))return message('Notifications unavailable. Export your calendar instead.');const p=await Notification.requestPermission();message(p==='granted'?'Reminders enabled while Rebound is open. Calendar export can notify when it is closed.':'Notifications not enabled. Calendar export is still available.');};
$('exportFocus').onclick=()=>download('rebound-focus-data.json',JSON.stringify({exportedAt:new Date().toISOString(),settings,profile,logs},null,2),'application/json');$('deleteFocus').onclick=async()=>{if(timer)return message('End your current session first.',true);if(!confirm('Permanently delete this device’s cloud focus history, schedule, and identity? Download your data first.'))return;try{await call('account','DELETE');logs=[];room='';localStorage.removeItem('rebound-room');await load();message('Cloud focus data deleted. A fresh empty profile is ready.');}catch(e){message(e.message,true);}};
$('saveIdentity').onclick=async()=>{try{const next={alias:$('studyAlias').value,exam:$('examGroup').value,public:$('publicLeaderboard').checked};await call('profile','PUT',next);profile=next;message('Study identity saved.');refreshLeaderboard();refreshRoom();}catch(e){message(e.message,true);}};
async function setRoom(code){room=code;localStorage.setItem('rebound-room',room);$('roomCode').value=code;await refreshRoom();message('Room joined. Your alias and focus status are shared with members.');}
$('createRoom').onclick=async()=>{try{await setRoom((await call('rooms','POST',{})).code);}catch(e){message(e.message,true);}};$('joinRoom').onclick=async()=>{try{await setRoom((await call('rooms/join','POST',{code:$('roomCode').value})).code);}catch(e){message(e.message,true);}};
async function refreshRoom(){if(!room){$('roomInfo').innerHTML='';$('roomMembers').innerHTML='<p class="muted">Create or join a room to study together.</p>';return;}try{const data=await call('rooms/'+room);$('roomInfo').innerHTML=`<div class="room-code"><span>Invite code</span><strong>${esc(room)}</strong><button id="copyRoom" class="quiet">Copy invite</button><button id="leaveRoom" class="quiet">Leave room</button></div>`;$('copyRoom').onclick=async()=>{try{await navigator.clipboard.writeText(room);message('Room code copied. Share it with people you want to join.');}catch{message('Copy this code: '+room);}};$('leaveRoom').onclick=async()=>{try{await call('rooms/leave','POST',{code:room});room='';localStorage.removeItem('rebound-room');refreshRoom();}catch(e){message(e.message,true);}};$('roomMembers').innerHTML=data.members.map((m,i)=>`<div class="person-row"><span class="person-avatar">${i+1}</span><div><strong>${esc(m.alias)}</strong><small>${esc(m.exam)} · ${m.online?(m.focusing?'Focusing now':'Here, getting ready'):'Away'}</small></div><strong>${Math.floor(m.seconds/60)} min</strong></div>`).join('');}catch(e){$('roomMembers').textContent=e.message;}}
async function refreshLeaderboard(){try{const data=await call('leaderboard?exam='+encodeURIComponent(profile.exam));$('leaderboardTitle').textContent=profile.exam+' · seven-day leaderboard';$('leaderboard').innerHTML=data.entries.length?data.entries.map((m,i)=>`<div class="person-row"><span class="person-avatar">${i+1}</span><strong>${esc(m.alias)}</strong><span>${Math.floor(m.seconds/60)} min</span></div>`).join(''):'<p class="muted">No public completed sessions in this group yet. Participation is optional.</p>';}catch(e){$('leaderboard').textContent=e.message;}}
$('refreshRoom').onclick=refreshRoom;$('refreshLeaderboard').onclick=refreshLeaderboard;setInterval(()=>{if(tab==='community'&&!document.hidden&&ready)refreshRoom();},20000);
async function sound(){if(soundContext){await soundContext.close();soundContext=null;soundNode=null;$('soundToggle').textContent='Play sound';return;}const choice=$('soundChoice').value;if(choice==='none')return message('Choose a soundscape first.');try{soundContext=new (window.AudioContext||window.webkitAudioContext)();const buffer=soundContext.createBuffer(1,soundContext.sampleRate*5,soundContext.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){let n=Math.random()*2-1;if(choice==='brown'){last=(last+.02*n)/1.02;n=last*3.5;}data[i]=n;}soundNode=soundContext.createBufferSource();soundNode.buffer=buffer;soundNode.loop=true;soundGain=soundContext.createGain();soundGain.gain.value=Number($('soundVolume').value)/100*.18;if(choice==='rain'){const filter=soundContext.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1700;soundNode.connect(filter);filter.connect(soundGain);}else soundNode.connect(soundGain);soundGain.connect(soundContext.destination);soundNode.start();$('soundToggle').textContent='Stop sound';}catch{message('Audio could not start.',true);}}
$('soundToggle').onclick=sound;$('soundChoice').onchange=async()=>{if(soundContext){await sound();await sound();}};$('soundVolume').oninput=()=>{if(soundGain&&soundContext)soundGain.gain.setTargetAtTime(Number($('soundVolume').value)/100*.18,soundContext.currentTime,.1);};
function bridge(){window.postMessage({source:'rebound-app',type:'sync-guard',config:settings,activeUntil:timer?.kind==='focus'&&timer.running?Date.now()+Math.max(0,timerRemaining(timer)):0},location.origin);}
window.addEventListener('message',e=>{if(e.source!==window||e.origin!==location.origin||e.data?.source!=='rebound-extension')return;if(e.data.type==='guard-status'){$('extensionStatus').textContent=e.data.active?'Browser guard is active':'Browser guard connected';$('extensionDetail').textContent='Applies in this desktop browser. You can disable the extension at any time.';const usage=e.data.usage||{};$('browserUsage').innerHTML='<h4>Today in this browser</h4>'+Object.entries(usage).map(([domain,seconds])=>`<p class="small">${esc(domain)} · ${Math.floor(Number(seconds)/60)} min</p>`).join('')+`<p class="small">${Number(e.data.blocked||0)} blocked page attempts today</p>`;}});
setInterval(()=>{if(ready)bridge();},15000);$('reloadFocus').onclick=load;load();window.dispatchEvent(new Event('rebound:focus-ready'));
